CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), broker text NOT NULL, mode text NOT NULL CHECK(mode IN ('backtest','paper','live')), currency text DEFAULT 'USD', balance numeric NOT NULL DEFAULT 0, equity numeric NOT NULL DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS instruments(symbol text PRIMARY KEY, base_currency text, quote_currency text, pip_size numeric NOT NULL, active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS market_data(symbol text REFERENCES instruments(symbol), timeframe text, ts timestamptz, open numeric, high numeric, low numeric, close numeric, volume numeric, PRIMARY KEY(symbol,timeframe,ts));
CREATE TABLE IF NOT EXISTS signals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts(id), symbol text, side text, score numeric, strategy text, regime text, session text, entry numeric, stop_loss numeric, take_profit numeric, explanation jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts(id), broker_order_id text, client_order_id text UNIQUE, symbol text, side text, units numeric, status text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS positions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts(id), symbol text, side text, units numeric, entry numeric, stop_loss numeric, take_profit numeric, opened_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS trades(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts(id), signal_id uuid REFERENCES signals(id), symbol text, direction text, entry numeric, exit numeric, stop_loss numeric, take_profit numeric, units numeric, risk numeric, pnl numeric, r_multiple numeric, exit_reason text, strategy text, regime text, session text, spread numeric, slippage numeric, ai_analysis jsonb, opened_at timestamptz, closed_at timestamptz);
CREATE TABLE IF NOT EXISTS strategies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE, config jsonb NOT NULL DEFAULT '{}', active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS risk_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts(id), event_type text, severity text, message text, metadata jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS news_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), currency text, impact text, title text, event_at timestamptz, metadata jsonb);
CREATE TABLE IF NOT EXISTS backtests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts(id), name text, config jsonb, started_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS backtest_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), backtest_id uuid REFERENCES backtests(id), trades integer, win_rate numeric, profit_factor numeric, expectancy numeric, sharpe numeric, sortino numeric, max_drawdown numeric, recovery_factor numeric, metrics jsonb);
CREATE TABLE IF NOT EXISTS model_predictions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), signal_id uuid REFERENCES signals(id), model text, score numeric, features jsonb, outcome numeric, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS system_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), level text, component text, message text, metadata jsonb, created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_market_symbol_ts ON market_data(symbol,ts DESC);
CREATE INDEX IF NOT EXISTS idx_signals_created ON signals(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_trades_account_closed ON trades(account_id,closed_at DESC);
CREATE INDEX IF NOT EXISTS idx_news_event ON news_events(event_at);
